        TimeSpan[] flightTimes = new TimeSpan[]
                          {new TimeSpan(2, 25, 0), new TimeSpan(1, 48, 0)};
        Console.WriteLine($"Takeoff is scheduled for {takeOff:d} at {takeOff:T}.");
        for (int ctr = flightTimes.GetLowerBound(0);
