        //       9/1/2007 6:45:00 AM -07:00 = 9/1/2007 6:45:00 AM -06:00: False
        //       9/1/2007 6:45:00 AM -07:00 = 9/1/2007 8:45:00 AM -05:00: True
        //       9/1/2007 6:45:00 AM -07:00 = : False
        //       9/1/2007 6:45:00 AM -07:00 = 9/1/2007 6:45:00 AM: False
        // </Snippet10>
