            // <Snippet3>
            Northwnd db = new Northwnd(@"c:\northwnd.mdf");
            decimal? totalSales = 0;
            db.CustOrderTotal("alfki", ref totalSales);

            Console.WriteLine(totalSales);
            // </Snippet3>
