        query1.ToList();
        Console.WriteLine("Count: " + count);

        //Reset the count variable.
        count = 0;

        var query2 = context
            .Contacts
            .Where(c => c.LastName == lastName)
            .Select(c => new MyContact { LastName = c.LastName })
