                              where p.PersonID == personID
                              select p).First();

                StudentGrade grade = new StudentGrade
                {
                    // The database will generate the EnrollmentID.
                    Grade = 4.0M,
                    // Use the navigation properties to create the association between the objects.
                    Course = course,
                    Person = student
