            {
                // Retrieve instructors hired more than 10 years ago.
                var instructors = from p in context.People
                                  where GetYearsEmployed(p) > 10
                                  select p;

                foreach (var instructor in instructors)
                {
                    Console.WriteLine(instructor.LastName);
                }
            }
        }
    }
}

