    {
        foreach (var element in arr)
        {
            _list.Add(element);
        }
    }

    public override IList<IEnumerator<T>> GetPartitions(int partitionCount)
    {
        List<IEnumerator<T>> enumList = new();
        enumList.Add(_list.GetEnumerator());
        return enumList;
    }
