        {
            get
            {
                return from name in names select name;
            }
        }

        public ReadOnlyCollection<string> Names_3
        {
            get
            {
                return names.AsReadOnly(); //return list as a ReadOnlyCollection
            }
        }

        public List<string> BadProp
        {
            get { return names; }
        }
    }

