        /// selected item in the myItems collection.</remarks>
        IRawElementProviderFragment IRawElementProviderFragmentRoot.GetFocus()
        {
            if (SelectedIndex >= 0)
            {
                return (IRawElementProviderFragment)myItems[SelectedIndex];
