using System;
using Microsoft.Data.Sqlite;

namespace AggregateFunctionSample
{
    class Program
    {
        static void Main()
        {
            var connection = new SqliteConnection("Data Source=:memory:");
            connection.Open();

            var createCommand = connection.CreateCommand();
            createCommand.CommandText =
            @"
                CREATE TABLE student (
                    gpa REAL
                );

                INSERT INTO student
                VALUES (4.0),
                       (3.0),
                       (3.0),
                       (2.0),
                       (2.0),
                       (2.0),
                       (2.0),
                       (1.0),
                       (1.0),
                       (0.0);
            ";
            createCommand.ExecuteNonQuery();

            #region snippet_CreateAggregate
            connection.CreateAggregate(
                "stdev",

                // A tuple to maintain context between rows
                (Count: 0, Sum: 0.0, SumOfSquares: 0.0),

                // This is called for each row
                ((int Count, double Sum, double SumOfSquares) context, double value) =>
                {
                    context.Count++;
                    context.Sum += value;
                    context.SumOfSquares += value * value;

                    return context;
                },

                // This is called to get the final result
                context =>
                {
                    var variance = context.SumOfSquares - context.Sum * context.Sum / context.Count;

                    return Math.Sqrt(variance / context.Count);
                });

            var command = connection.CreateCommand();
            command.CommandText =
            @"
                SELECT stdev(gpa)
                FROM student
            ";
            var stdDev = command.ExecuteScalar();
            #endregion

            Console.WriteLine($"Standard deviation: {stdDev}");
        }
    }
}

using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Data.Sqlite;

namespace AsyncSample
{
    class Program
    {
        static async Task Main()
        {
            // SQLite doesn't support asynchronous I/O. Instead, they recommend using a
            // write-ahead log (WAL) which improves write performance. This sample
            // demonstrates the anti-pattern of using ADO.NET's async methods with
            // Microsoft.Data.Sqlite.

            #region snippet_WAL
            var connection = new SqliteConnection("Data Source=AsyncSample.db");
            connection.Open();

            // Enable write-ahead logging
            var walCommand = connection.CreateCommand();
            walCommand.CommandText =
            @"
                PRAGMA journal_mode = 'wal'
            ";
            walCommand.ExecuteNonQuery();
            #endregion

            var createCommand = connection.CreateCommand();
            createCommand.CommandText =
            @"
                CREATE TABLE data (
                    value BLOB
                )
            ";
            createCommand.ExecuteNonQuery();

            var insertCommand = connection.CreateCommand();
            insertCommand.CommandText =
            @"
                INSERT INTO data
                VALUES ($value)
            ";

            Console.WriteLine("Generating 100 MB of data...");
            var value = new byte[100_000_000];
            var random = new Random();
            random.NextBytes(value);
            insertCommand.Parameters.AddWithValue("$value", value);

            Console.WriteLine("Inserting data...");
            var stopwatch = Stopwatch.StartNew();
            var task = insertCommand.ExecuteNonQueryAsync();
            Console.WriteLine($"Blocked for {stopwatch.ElapsedMilliseconds} ms");

            stopwatch.Restart();
            await task;
            Console.WriteLine($"Yielded for {stopwatch.ElapsedMilliseconds} ms");

            // Clean up
            connection.Close();
            File.Delete("AsyncSample.db");
        }
    }
}

